window.addEventListener('DOMContentLoaded',()=>{
const $=s=>document.querySelector(s);const scenario=window.UxdScenario?.get()||new URLSearchParams(location.search).get('scenario')||'default';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let assets=JSON.parse(sessionStorage.getItem('asr-assets')||'[{"name":"Whisper large v3","url":"https://whisper.example.test/v1","asr":true}]');
const notice=(text,error=false)=>{$('#notice').className='alert '+(error?'error':'');$('#notice').textContent=text;$('#notice').hidden=false;};
if(document.body.dataset.page==='assets'){
if(scenario==='empty')assets=[];
if(scenario==='unflagged')assets=[{name:'Whisper endpoint',url:'https://whisper.example.test/v1',asr:false}];
function render(){ $('#rows').innerHTML=assets.map((a,i)=>`<tr><td>${esc(a.name)}</td><td>${esc(a.url)}</td><td><label><input type="checkbox" data-index="${i}" ${a.asr?'checked':''}> ASR / transcription</label></td></tr>`).join('');$('#empty').hidden=assets.length>0;document.querySelectorAll('[data-index]').forEach(c=>c.onchange=()=>{assets[c.dataset.index].asr=c.checked;sessionStorage.setItem('asr-assets',JSON.stringify(assets));notice('Endpoint capabilities updated. The Playground audio model list is ready.');});}
render();if(scenario==='load-error'){ $('#rows').innerHTML='';notice('Unable to load AI Asset endpoints. Retry to reconnect.',true);$('#retry').hidden=false;}
$('#retry').onclick=()=>{render();$('#notice').hidden=true;$('#retry').hidden=true;};
$('#register').onclick=()=>$('#dialog').showModal();$('#cancel').onclick=()=>$('#dialog').close();
$('#asset-form').onsubmit=e=>{e.preventDefault();assets.push({name:$('#name').value,url:$('#endpoint').value,asr:$('#asr-flag').checked});sessionStorage.setItem('asr-assets',JSON.stringify(assets));render();$('#dialog').close();notice('AI Asset registered. Return to Playground to select your transcription model.');};return;
}
let file=null,used=false,busy=false,kind='image';const models={vision:['image'],audio:['audio'],text:[],unknown:['image','audio']};
function controls(){const caps=models[$('#model').value];$('#inputs').innerHTML=caps.map(c=>`<button type="button" id="${c}" data-ouia-component-id="attach-${c}">Attach ${c}</button>`).join('');caps.forEach(c=>$('#'+c).onclick=()=>{if(used||file)return notice('Only one image or audio file is allowed per conversation. Start a new chat to attach another.',true);kind=c;$('#file').accept=c==='image'?'image/jpeg,image/png':'audio/wav,audio/x-wav,audio/mpeg';$('#file').click();});$('#audio-models').hidden=!caps.includes('audio');$('#asr').innerHTML='<option value="">Select a transcription model</option>'+assets.filter(a=>a.asr).map(a=>`<option>${esc(a.name)}</option>`).join('');if(assets.filter(a=>a.asr).length===1)$('#asr').selectedIndex=1;if(caps.includes('audio')&&!assets.some(a=>a.asr))notice('Register a transcription model as an AI Asset to submit audio. Use AI Asset endpoints above.',true);}
$('#model').onchange=()=>{file=null;$('#attachment').innerHTML='';$('#notice').hidden=true;controls();};
function attach(f){if(used||file)return notice('Only one image or audio file is allowed per conversation. Start a new chat to attach another.',true);if(!f.size)return notice('The file is empty. Choose a non-empty file.',true);if(f.size>10*1024*1024)return notice('File exceeds the 10 MB prototype limit. Choose a smaller file.',true);if(!(kind==='image'?['image/jpeg','image/png']:['audio/wav','audio/x-wav','audio/mpeg']).includes(f.type))return notice('Unsupported file type. Images: JPG or PNG. Audio: WAV or MP3. PDF uses Upload files outside this prototype.',true);file={name:f.name,type:kind,url:URL.createObjectURL(f)};showFile();notice('File ready. Upload and inference are simulated in this prototype.');}
function showFile(){$('#attachment').innerHTML=`<p>${esc(file.name)} <button id="remove" type="button">Remove</button></p>`;$('#remove').onclick=()=>{file=null;$('#attachment').innerHTML='';};}
$('#file').onchange=e=>{if(e.target.files[0])attach(e.target.files[0]);e.target.value='';};
$('#new-chat').onclick=()=>{used=false;file=null;busy=false;$('#send').disabled=false;$('#transcript').innerHTML='<div class="empty">Start a conversation with text, an image, or an audio file.</div>';$('#attachment').innerHTML='';$('#prompt').value='';$('#notice').hidden=true;};
$('#composer').onsubmit=e=>{e.preventDefault();if(busy)return;const prompt=$('#prompt').value.trim();if(!prompt&&!file)return notice('Enter a message or attach a file.',true);if(file?.type==='audio'&&!$('#asr').value)return notice('Select a registered transcription model before submitting audio.',true);if(file&&$('#model').value==='unknown')return notice('This model rejected the attachment. Its capability metadata is unavailable. Choose a supported model or remove the file.',true);busy=true;$('#send').disabled=true;notice(file?.type==='audio'?'Transcribing audio, then generating a response…':'Processing your request…');const pending=file;setTimeout(()=>{if(!busy)return;const t=$('#transcript');t.querySelector('.empty')?.remove();t.insertAdjacentHTML('beforeend',`<div class="message"><strong>You</strong>${esc(prompt)}${pending?`<p>${esc(pending.name)}</p>`:''}${pending?.url?(pending.type==='image'?`<img class="preview" alt="Uploaded image" src="${pending.url}">`:`<audio controls src="${pending.url}"></audio>`):''}</div><div class="message"><strong>Assistant <span class="badge">Mock response</span></strong>${pending?.type==='audio'?'Transcription: “Please summarize the quarterly results.”<p>The speaker requests a summary of quarterly results.</p>':pending?'The image has been received. This sample response demonstrates where the model’s visual analysis appears.':'This is a simulated text response. You can continue this conversation.'}</div>`);used=used||!!pending;file=null;$('#attachment').innerHTML='';$('#prompt').value='';busy=false;$('#send').disabled=false;notice(used?'Response complete. This conversation has used its one attachment. Text follow-ups are available.':'Response complete.');},650);};
if(scenario==='no-asr'){assets=[];$('#model').value='audio';}
if(scenario==='text-only')$('#model').value='text';
if(['audio-success','asr-error','empty-transcription'].includes(scenario))$('#model').value='audio';
controls();
if(scenario==='image-success'||scenario==='audio-success'){used=true;$('#transcript').innerHTML=`<div class="message"><strong>You</strong>${scenario==='image-success'?'<img class="preview" src="sample.svg" alt="Sample quarterly bar chart"><p>Summarize this chart.</p>':'<p>quarterly-update.wav</p><p>Transcription: Revenue increased by 12 percent.</p>'}</div><div class="message"><strong>Assistant <span class="badge">Mock response</span></strong>Revenue increased by 12% this quarter.</div>`;notice('Response complete. One attachment used. Start a new chat to attach another file.');}
if(scenario==='asr-error')notice('Transcription failed: the ASR endpoint is unreachable. Select another transcription model and retry. No prompt was sent to the chat model.',true);
if(scenario==='empty-transcription')notice('No speech was detected. Choose an audio file with audible speech. No prompt was sent to the chat model.',true);
});
